proc routeShapesModule[T](instance: T, bare: string, params: openArray[byte]): Result[seq[byte], InvocationFailure] =
  mixin `pick`, `ping`, `reflect`
  let request = ?kitValidator().checkedRequest(bare, params)
  if bare == "pick":
    let response = ?`pick`(instance, fromChecked(ShapesPickRequest, request))
    return encodedResponse(encode(response))
  if bare == "ping":
    let response = ?`ping`(instance, fromChecked(ShapesPingRequest, request))
    return encodedResponse(encode(response))
  if bare == "reflect":
    let response = ?`reflect`(instance, fromChecked(ShapesReflectRequest, request))
    return encodedResponse(encode(response))
  discard request
  err(failure(ecMethodNotFound, "unknown method " & bare))

